INSERT INTO "jobs" VALUES('wanted','https://www.wanted.co.kr/wd/392461','{"collected_at":"2026-11-14T00:00:53.344357+00:00","company":"누리하우스","deadline":"2026-11-30","description":"[평가·보상 체계 수립] • 성과 평가 제도, 직급 체계, 보상 정책 설계 및 첫 평가 사이클 운영 [인사 운영 및 노무] • 사내 규정 정비, 노무 이슈 및 법적 의무사항 대응 • 채용·온보딩 운영, 외부 노무·세무 파트너와 협업한 급여 관리 [총무 및 대관] • 오피스, 자산, 계약서 관리 및 법인 행정 • 정부지원사업, 외국인 구성원 비자 등 유관기관 대응 [경영진 파트너십 및 조직 진단] • 경영진과 협업해 인력 계획, 조직 구조 등 의사결정 지원 및 필요한 관점과 데이터 제공 • 인사 데이터를 근거로 조직문화와 구성원 경험을 진단하고 개선 방향 제안 HR, 인사담당, 노무·노사, 급여담당","employment_type":"regular","experience":"경력 8~10년 / 정규직","keyword":"인사","link":"https://www.wanted.co.kr/wd/392461","location":"한국 서울 강남구 서울 강남구 언주로 622, 6층","matched_keywords":["인사"],"site":"wanted","source_url":"https://www.wanted.co.kr/api/chaos/search/v1/position?query=%EC%9D%B8%EC%82%AC&country=kr&years=-1&locations=all&sort=job.recommend_order&limit=20&offset=0","title":"인사/총무 팀장 [경력 8~10년 / 정규직]"}','e0fe7d77586ab9be613f3b8d90fba89a6baeaca1de8ac420a543d023c2e2369b','2026-10-17T17:35:26+00:00','2026-11-14T00:01:27+00:00','2026-10-17T17:35:26+00:00');
